    <div id="p9zgztn">
      <section class="TextGraySixHundredElement body-font">
        <div class="ContainerElement PaddingXFiveElement PaddingYTwentyFourElement MarginXAutoElement">
          <div class="TextCenterElement MarginBTwentyElement">
            <h1 class="SmallTextThreeXLElement TextTwoXLElement FontMediumElement title-font TextGrayNineHundredElement MarginBFourElement">A Considered Approach to Interior Design</h1>
            <p class="TextBaseElement LeadingRelaxedElement ExtraLargeWidthTwoQuarterElement LargeWidthThreeQuarterElement MarginXAutoElement text-gray-500s">
              Good interior design is not only about how a room looks in a photograph. It also considers movement, storage, light, comfort and the routines that shape daily life. Pale Stone Interiors takes a measured approach, connecting these practical considerations with colour, texture and form. The result is a design direction that can help you understand your options and make choices with a clearer sense of how the elements work together.
            </p>
            <div class="FlexElement MarginTSixElement JustifyCenterElement">
              <div class="WidthSixteenElement HeightOneElement RoundedFullElement BackgroundRedFiveHundredElement InlineFlexElement"></div>
            </div>
          </div>
          <div class="FlexElement FlexWrapElement SmallNegativeMarginFourElement NegativeMarginXFourElement NegativeMarginBTenElement NegativeMarginTFourElement MediumSpaceYZeroElement SpaceYSixElement">
            <div class="PaddingFourElement MediumWidthOneThirdElement FlexElement FlexColElement TextCenterElement ItemsCenterElement">
              <div class="WidthTwentyElement HeightTwentyElement InlineFlexElement ItemsCenterElement JustifyCenterElement RoundedFullElement BackgroundRedOneHundredElement TextRedFiveHundredElement MarginBFiveElement FlexShrinkZeroElement">
                <svg class="WidthTenElement HeightTenElement" fill="currentColor" xmlns="http://www.w3.org/2000/svg" id="cugr" data-name="Layer 1" viewBox="0 0 24 24" width="512" height="512">
